// Packs everything in public/ into worker/pages.generated.js so the Worker
// can serve the web pages itself. Runs automatically before `wrangler dev`
// and `wrangler deploy` (see "build" in wrangler.jsonc).
const fs = require('node:fs');
const path = require('node:path');

const dir = path.join(__dirname, '..', 'public');
const types = { '.html': 'text/html; charset=utf-8', '.css': 'text/css; charset=utf-8', '.js': 'text/javascript; charset=utf-8', '.svg': 'image/svg+xml' };
const pages = {};
for (const file of fs.readdirSync(dir)) {
  const type = types[path.extname(file)];
  if (!type) continue;
  const body = fs.readFileSync(path.join(dir, file), 'utf8');
  pages['/' + file] = [body, type];
  if (file.endsWith('.html')) pages['/' + file.replace(/\.html$/, '')] = [body, type];
}
pages['/'] = pages['/index.html'];
delete pages['/index'];
fs.writeFileSync(path.join(__dirname, '..', 'worker', 'pages.generated.js'), `// Generated by scripts/bundle-pages.js — do not edit.\nexport const PAGES = ${JSON.stringify(pages)};\n`);
console.log(`Bundled ${Object.keys(pages).length} routes from public/`);
